Used the aura-uiux skill to pull the iOS HIG and Material 3 rules plus the semantic-token/dark-mode ladder before writing this, so a few choices below are platform-driven rather than arbitrary:

- **Delete confirmation** uses `ActionSheetIOS` on iOS (destructive action sheet tied to the triggering row, Cancel separated) and `Alert.alert` on Android (a two-action dialog) — HIG and Material 3 prefer different containers for the same "destructive, must confirm" moment.
- **Touch targets** are `minHeight: 48` (satisfies Apple's 44pt floor and Material's 48dp floor at once) rather than two different row heights.
- **Dark mode** follows the "lighter = nearer" elevation ladder (`bg.app` → `bg.surface` → `bg.surfaceRaised`) instead of darkening nested surfaces or relying on shadows, which barely read on OLED blacks.
- Row labels don't truncate with a fixed line count — they wrap, and rows have `minHeight` not `height`, so Dynamic Type / large Android font scales grow the row instead of clipping text.

```tsx
// AccountSettingsScreen.tsx
// Requires: react-native, react-native-safe-area-context, @expo/vector-icons
// (swap Ionicons for react-native-vector-icons/Ionicons if not on Expo)

import React, { useCallback, useMemo, useState } from 'react';
import {
  View,
  Text,
  Pressable,
  Switch,
  Image,
  ActionSheetIOS,
  Alert,
  Platform,
  StyleSheet,
  useColorScheme,
  ScrollView,
  ActivityIndicator,
  AccessibilityInfo,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { Ionicons } from '@expo/vector-icons';

// ---------------------------------------------------------------------------
// Semantic tokens — primitives are never read by components directly.
// Dark mode uses the "lighter = nearer" elevation ladder (level 0 -> 2),
// not darker/shadowed surfaces, which is how Material 3 and HIG both model depth.
// ---------------------------------------------------------------------------

type Tokens = {
  bgApp: string;
  bgSurface: string; // level 1: cards, grouped sections
  bgSurfaceRaised: string; // level 2: nothing used here, reserved for sheets
  borderSubtle: string;
  textPrimary: string;
  textMuted: string;
  accentSolid: string;
  dangerText: string;
  dangerSolid: string;
  overlayScrim: string;
};

const lightTokens: Tokens = {
  bgApp: '#F2F2F5',
  bgSurface: '#FFFFFF',
  bgSurfaceRaised: '#FFFFFF',
  borderSubtle: '#E2E2E6',
  textPrimary: '#17171A',
  textMuted: '#6C6C72',
  accentSolid: Platform.select({ ios: '#0A84FF', android: '#6750A4', default: '#0A84FF' })!,
  dangerText: '#D92D20',
  dangerSolid: '#D92D20',
  overlayScrim: 'rgba(0,0,0,0.4)',
};

const darkTokens: Tokens = {
  bgApp: '#121214', // avoid pure black for large areas
  bgSurface: '#1C1C1F', // level 1, lighter than bgApp
  bgSurfaceRaised: '#262629', // level 2, lighter still
  borderSubtle: '#34343A',
  textPrimary: '#F2F2F3',
  textMuted: '#9B9BA1',
  accentSolid: Platform.select({ ios: '#409CFF', android: '#D0BCFF', default: '#409CFF' })!,
  dangerText: '#FF6B61',
  dangerSolid: '#FF453A',
  overlayScrim: 'rgba(0,0,0,0.6)',
};

function useTokens(): Tokens {
  const scheme = useColorScheme();
  return scheme === 'dark' ? darkTokens : lightTokens;
}

// ---------------------------------------------------------------------------
// Data shapes
// ---------------------------------------------------------------------------

type Profile = {
  name: string;
  email: string;
  avatarUri?: string;
};

type ToggleRow = {
  key: string;
  kind: 'toggle';
  icon: keyof typeof Ionicons.glyphMap;
  label: string;
  value: boolean;
  onToggle: (next: boolean) => void;
};

type NavRow = {
  key: string;
  kind: 'nav';
  icon: keyof typeof Ionicons.glyphMap;
  label: string;
  valueLabel?: string;
  onPress: () => void;
};

type SettingsRowData = ToggleRow | NavRow;

type Section = {
  key: string;
  title?: string;
  rows: SettingsRowData[];
};

// ---------------------------------------------------------------------------
// Profile row
// ---------------------------------------------------------------------------

function ProfileRow({
  profile,
  tokens,
  onPress,
}: {
  profile: Profile;
  tokens: Tokens;
  onPress: () => void;
}) {
  const initials = profile.name
    .split(' ')
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase())
    .join('');

  return (
    <Pressable
      onPress={onPress}
      accessibilityRole="button"
      accessibilityLabel={`${profile.name}, ${profile.email}. Edit profile`}
      style={({ pressed }) => [
        styles.profileRow,
        { backgroundColor: tokens.bgSurface, borderColor: tokens.borderSubtle },
        pressed && { opacity: 0.6 },
      ]}
    >
      {profile.avatarUri ? (
        <Image source={{ uri: profile.avatarUri }} style={styles.avatar} />
      ) : (
        <View style={[styles.avatar, styles.avatarFallback, { backgroundColor: tokens.accentSolid }]}>
          <Text style={styles.avatarInitials}>{initials || '?'}</Text>
        </View>
      )}
      <View style={styles.profileText}>
        <Text style={[styles.profileName, { color: tokens.textPrimary }]} numberOfLines={2}>
          {profile.name}
        </Text>
        <Text style={[styles.profileEmail, { color: tokens.textMuted }]} numberOfLines={2}>
          {profile.email}
        </Text>
      </View>
      <Ionicons name="chevron-forward" size={20} color={tokens.textMuted} />
    </Pressable>
  );
}

// ---------------------------------------------------------------------------
// Generic settings row (nav or toggle)
// ---------------------------------------------------------------------------

function SettingsRow({
  row,
  tokens,
  isLast,
}: {
  row: SettingsRowData;
  tokens: Tokens;
  isLast: boolean;
}) {
  const content = (
    <View
      style={[
        styles.row,
        !isLast && { borderBottomWidth: 1, borderBottomColor: tokens.borderSubtle },
      ]}
    >
      <Ionicons name={row.icon} size={22} color={tokens.textMuted} style={styles.rowIcon} />
      <Text style={[styles.rowLabel, { color: tokens.textPrimary }]}>{row.label}</Text>
      {row.kind === 'nav' ? (
        <View style={styles.rowTrailing}>
          {row.valueLabel ? (
            <Text style={[styles.rowValue, { color: tokens.textMuted }]} numberOfLines={1}>
              {row.valueLabel}
            </Text>
          ) : null}
          <Ionicons name="chevron-forward" size={18} color={tokens.textMuted} />
        </View>
      ) : (
        <Switch
          value={row.value}
          onValueChange={row.onToggle}
          accessibilityLabel={row.label}
          accessibilityRole="switch"
          trackColor={{ true: tokens.accentSolid }}
        />
      )}
    </View>
  );

  if (row.kind === 'toggle') {
    // Switch itself owns the native hit target; wrapping it in another
    // Pressable would create two overlapping targets.
    return content;
  }

  return (
    <Pressable
      onPress={row.onPress}
      accessibilityRole="button"
      accessibilityLabel={row.label}
      style={({ pressed }) => pressed && { opacity: 0.6 }}
    >
      {content}
    </Pressable>
  );
}

function SettingsSection({
  section,
  tokens,
}: {
  section: Section;
  tokens: Tokens;
}) {
  return (
    <View style={styles.section}>
      {section.title ? (
        <Text style={[styles.sectionTitle, { color: tokens.textMuted }]}>{section.title}</Text>
      ) : null}
      <View style={[styles.sectionBody, { backgroundColor: tokens.bgSurface, borderColor: tokens.borderSubtle }]}>
        {section.rows.map((row, index) => (
          <SettingsRow key={row.key} row={row} tokens={tokens} isLast={index === section.rows.length - 1} />
        ))}
      </View>
    </View>
  );
}

// ---------------------------------------------------------------------------
// Delete account — confirmation container differs per platform on purpose:
// HIG asks for a destructive action sheet anchored to the control that
// started it; Material asks for a short two-action dialog. Alert.alert
// already renders as that native dialog on Android, so only iOS branches.
// ---------------------------------------------------------------------------

function useDeleteAccountFlow(onConfirmedDelete: () => Promise<void>) {
  const [isDeleting, setIsDeleting] = useState(false);

  const runDelete = useCallback(async () => {
    setIsDeleting(true);
    try {
      await onConfirmedDelete();
      AccessibilityInfo.announceForAccessibility('Account deleted');
    } catch (err) {
      Alert.alert('Couldn’t delete account', 'Please try again.');
    } finally {
      setIsDeleting(false);
    }
  }, [onConfirmedDelete]);

  const confirmDelete = useCallback(() => {
    if (Platform.OS === 'ios') {
      ActionSheetIOS.showActionSheetWithOptions(
        {
          title: 'Delete Account',
          message: 'This permanently deletes your account and all of your data. This can’t be undone.',
          options: ['Delete Account', 'Cancel'],
          destructiveButtonIndex: 0,
          cancelButtonIndex: 1,
        },
        (buttonIndex) => {
          if (buttonIndex === 0) {
            runDelete();
          }
        },
      );
    } else {
      Alert.alert(
        'Delete account?',
        'This permanently deletes your account and all of your data. This can’t be undone.',
        [
          { text: 'Cancel', style: 'cancel' },
          { text: 'Delete Account', style: 'destructive', onPress: () => runDelete() },
        ],
      );
    }
  }, [runDelete]);

  return { confirmDelete, isDeleting };
}

function DeleteAccountButton({
  tokens,
  onConfirmedDelete,
}: {
  tokens: Tokens;
  onConfirmedDelete: () => Promise<void>;
}) {
  const { confirmDelete, isDeleting } = useDeleteAccountFlow(onConfirmedDelete);

  return (
    <Pressable
      onPress={confirmDelete}
      disabled={isDeleting}
      accessibilityRole="button"
      accessibilityLabel="Delete account"
      accessibilityHint="Opens a confirmation before permanently deleting your account"
      style={({ pressed }) => [
        styles.deleteRow,
        { backgroundColor: tokens.bgSurface, borderColor: tokens.borderSubtle },
        pressed && { opacity: 0.6 },
      ]}
    >
      {isDeleting ? (
        <ActivityIndicator color={tokens.dangerSolid} />
      ) : (
        <>
          <Ionicons name="trash-outline" size={20} color={tokens.dangerText} style={styles.rowIcon} />
          <Text style={[styles.deleteLabel, { color: tokens.dangerText }]}>Delete Account</Text>
        </>
      )}
    </Pressable>
  );
}

// ---------------------------------------------------------------------------
// Screen
// ---------------------------------------------------------------------------

export default function AccountSettingsScreen({
  profile,
  onEditProfile,
  onDeleteAccount,
}: {
  profile: Profile;
  onEditProfile: () => void;
  onDeleteAccount: () => Promise<void>;
}) {
  const tokens = useTokens();

  const [pushEnabled, setPushEnabled] = useState(true);
  const [faceIdEnabled, setFaceIdEnabled] = useState(false);

  const sections: Section[] = useMemo(
    () => [
      {
        key: 'preferences',
        title: 'Preferences',
        rows: [
          {
            key: 'push',
            kind: 'toggle',
            icon: 'notifications-outline',
            label: 'Push Notifications',
            value: pushEnabled,
            onToggle: setPushEnabled,
          },
          {
            key: 'language',
            kind: 'nav',
            icon: 'language-outline',
            label: 'Language',
            valueLabel: 'English',
            onPress: () => {},
          },
        ],
      },
      {
        key: 'security',
        title: 'Security',
        rows: [
          {
            key: 'password',
            kind: 'nav',
            icon: 'lock-closed-outline',
            label: 'Change Password',
            onPress: () => {},
          },
          {
            key: 'biometric',
            kind: 'toggle',
            icon: 'finger-print-outline',
            label: Platform.OS === 'ios' ? 'Face ID / Touch ID' : 'Biometric Unlock',
            value: faceIdEnabled,
            onToggle: setFaceIdEnabled,
          },
        ],
      },
      {
        key: 'support',
        title: 'Support',
        rows: [
          {
            key: 'help',
            kind: 'nav',
            icon: 'help-circle-outline',
            label: 'Help & Support',
            onPress: () => {},
          },
          {
            key: 'privacy',
            kind: 'nav',
            icon: 'shield-checkmark-outline',
            label: 'Privacy Policy',
            onPress: () => {},
          },
          {
            key: 'terms',
            kind: 'nav',
            icon: 'document-text-outline',
            label: 'Terms of Service',
            onPress: () => {},
          },
        ],
      },
    ],
    [pushEnabled, faceIdEnabled],
  );

  return (
    <SafeAreaView style={[styles.screen, { backgroundColor: tokens.bgApp }]} edges={['bottom', 'left', 'right']}>
      <ScrollView
        contentContainerStyle={styles.scrollContent}
        contentInsetAdjustmentBehavior="automatic"
      >
        <ProfileRow profile={profile} tokens={tokens} onPress={onEditProfile} />

        {sections.map((section) => (
          <SettingsSection key={section.key} section={section} tokens={tokens} />
        ))}

        <View style={styles.section}>
          <DeleteAccountButton tokens={tokens} onConfirmedDelete={onDeleteAccount} />
        </View>
      </ScrollView>
    </SafeAreaView>
  );
}

// ---------------------------------------------------------------------------
// Styles — row heights use minHeight so Dynamic Type / large Android fonts
// grow the row instead of clipping; 48 satisfies iOS's 44pt and Android's
// 48dp minimum target at once.
// ---------------------------------------------------------------------------

const styles = StyleSheet.create({
  screen: {
    flex: 1,
  },
  scrollContent: {
    paddingHorizontal: 16,
    paddingTop: 16,
    paddingBottom: 32,
    gap: 24,
  },
  profileRow: {
    flexDirection: 'row',
    alignItems: 'center',
    minHeight: 64,
    borderRadius: 14,
    borderWidth: 1,
    paddingHorizontal: 16,
    paddingVertical: 12,
    gap: 12,
  },
  avatar: {
    width: 48,
    height: 48,
    borderRadius: 24,
  },
  avatarFallback: {
    alignItems: 'center',
    justifyContent: 'center',
  },
  avatarInitials: {
    color: '#FFFFFF',
    fontSize: 18,
    fontWeight: '600',
  },
  profileText: {
    flex: 1,
    gap: 2,
  },
  profileName: {
    fontSize: 17,
    fontWeight: '600',
    flexWrap: 'wrap',
  },
  profileEmail: {
    fontSize: 14,
    flexWrap: 'wrap',
  },
  section: {
    gap: 8,
  },
  sectionTitle: {
    fontSize: 13,
    fontWeight: '600',
    textTransform: 'uppercase',
    letterSpacing: 0.4,
    marginLeft: 4,
  },
  sectionBody: {
    borderRadius: 14,
    borderWidth: 1,
    overflow: 'hidden',
  },
  row: {
    flexDirection: 'row',
    alignItems: 'center',
    minHeight: 48,
    paddingHorizontal: 16,
    paddingVertical: 10,
    gap: 12,
  },
  rowIcon: {
    width: 22,
  },
  rowLabel: {
    flex: 1,
    fontSize: 16,
    flexWrap: 'wrap',
  },
  rowTrailing: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 6,
    flexShrink: 0,
  },
  rowValue: {
    fontSize: 15,
    maxWidth: 140,
  },
  deleteRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    minHeight: 48,
    borderRadius: 14,
    borderWidth: 1,
    paddingHorizontal: 16,
  },
  deleteLabel: {
    fontSize: 16,
    fontWeight: '600',
  },
});
```

Notes on wiring it up:
- `profile`, `onEditProfile`, and `onDeleteAccount` are props so the screen stays presentational — `onDeleteAccount` should call your API and resolve/reject; the button handles the loading spinner and error alert.
- Assumes it's pushed inside a navigator stack that supplies the header/back button — this component only owns the body content, per the "never put a second back control in the content" rule.
- Add more `ToggleRow`/`NavRow` entries to `sections` for additional settings; the row renderer and dividers scale automatically.
